import{_ as i,l as n,o as e,c as l,v as o,p as s,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"部分冗余消除","description":"","frontmatter":{"title":"部分冗余消除","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/partial-redundancy-elim.md","filePath":"cs/partial-redundancy-elim.md","lastUpdated":1789023840000}'),E={name:"cs/partial-redundancy-elim.md"};function h(m,a,_,u,f,A){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="部分冗余消除" tabindex="-1">部分冗余消除 <a class="header-anchor" href="#部分冗余消除" aria-label="Permalink to &quot;部分冗余消除&quot;">​</a></h1><div class="epigraph"><p>表达式在某些路径上已算过、某些没有：在缺少的路径上插入计算，使汇合点可用，再删除冗余。这是全局 CSE 与 LICM 的共同推广。</p><footer>—— 据 Morel and Renvoise, Global Optimization by Suppression of Partial Redundancies, 1979；Knoop, Rüthing and Steffen, Lazy Code Motion 整理</footer></div><p>上一课<a href="/cs/sroa">SROA</a>把更多表达式变成标量。缺口是<strong>部分冗余</strong>：<code>a+b</code> 在 <code>if</code> 的一枝算过，汇合后再算。PRE / lazy code motion：插入使变成完全可用，且尽量懒（不无故延长存活）。本课钉思想，不把全部数据流方程展开成作业。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可用表达式要求<strong>所有</strong>前驱都可用才消除。部分：有的前驱有。插入：在没有的前驱出口补上。缺口是<strong>插入点选择</strong>，避免多余计算与非法投机（陷阱）。</p><p>LCM（lazy code motion）把计算下移到尽可能晚，减寄存器压力。</p><h3 id="插入不是随便投机" tabindex="-1">插入不是随便投机 <a class="header-anchor" href="#插入不是随便投机" aria-label="Permalink to &quot;插入不是随便投机&quot;">​</a></h3><p>不能在不执行的路径上插入可能除零的运算，除非证明安全或原程序也会执行。与 LICM 的「必执行」同一类约束。</p><p><span class="marginnote">Morel–Renvoise 1979。Knoop–Rüthing–Steffen LCM。龙书 9.5 相关。LLVM 有 GVN-PRE。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据流：预期（anticipated）、可用、稍后。解方程，标记插入与删除。SSA 上可用 φ 与新名实现。</p>',11)),(e(),s(c,null,{default:t(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRED%5B%22%E9%83%A8%E5%88%86%E8%B7%AF%E5%BE%84%E5%B7%B2%E6%9C%89%20e%22%5D%20--%3E%20INS%5B%22%E7%BC%BA%E7%9A%84%E8%B7%AF%E5%BE%84%E6%8F%92%E5%85%A5%20e%22%5D%0A%20%20INS%20--%3E%20FULL%5B%22%E6%B1%87%E5%90%88%E5%90%8E%E5%AE%8C%E5%85%A8%E5%8F%AF%E7%94%A8%22%5D%0A%20%20FULL%20--%3E%20DEL%5B%22%E5%88%A0%E9%99%A4%E5%86%97%E4%BD%99%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与 GVN：先编号再 PRE，识别代数等价。与循环：不变式外提是 PRE 的特例（环外插入）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>代码体积：插入复制运算。临界边（从多后继到多前驱）要拆，否则插入点不唯一——CFG 变换。不要在 PRE 里移动 store；那是另一套（store PRE 更危险）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 LCM 最优性。后课默认：部分冗余可经插入变成 CSE。下一课值范围：另一格，服务消除比较与越界。</p><p>也不把 PRE 当死代码（那是删除无观察，不是移动计算）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PRE：插入补齐路径，消除部分冗余。</li><li>懒移动减寄存器压力；投机受陷阱约束。</li><li>LICM 是循环上的特例。</li><li>出处：Morel and Renvoise, 1979；Knoop et al. LCM；龙书。</li></ul>',8))])}const S=i(E,[["render",h]]);export{C as __pageData,S as default};
